1	#ifndef PSS_COMMON_IPC_H
2	#define PSS_COMMON_IPC_H
3	
4	/*
5	 * Daemon <-> hub messages over AF_UNIX SOCK_SEQPACKET (DESIGN.md Section 2): one
6	 * fixed-size struct per packet, so boundaries are preserved and a dead peer
7	 * shows up as EOF/EPIPE. All processes run on the same Pi, so the struct is
8	 * sent in native layout.
9	 */
10	
11	#include <stddef.h>
12	#include <stdint.h>
13	
14	#define PSS_IPC_VER 1
15	#define PSS_NBANDS 8
16	
17	enum pss_role {
18		PSS_ROLE_NONE = 0,
19		PSS_ROLE_PIR = 1,
20		PSS_ROLE_CAM = 2,
21		PSS_ROLE_MIC = 3,
22	};
23	
24	enum pss_msg_type {
25		PSS_MSG_HELLO = 1,	/* daemon -> hub, first message */
26		PSS_MSG_HEARTBEAT,	/* daemon -> hub, every 5 s */
27		PSS_MSG_PIR_EDGE,	/* pird -> hub */
28		PSS_MSG_CAM_TRIGGER,	/* hub -> camd */
29		PSS_MSG_CAM_DONE,	/* camd -> hub */
30		PSS_MSG_MIC_FRAME,	/* micd -> hub, 50 Hz */
31	};
32	
33	struct pss_msg {
34		uint16_t type;
35		uint16_t ver;
36		uint32_t seq;
37		int64_t mono_ns;	/* CLOCK_MONOTONIC; for PIR edges, the kernel's edge timestamp */
38		union {
39			struct { uint32_t role; uint32_t pid; } hello;
40			struct { uint64_t dropped; uint64_t count; } hb;
41			struct { uint32_t rising; uint32_t pad; } pir;
42			struct { uint64_t event_id; uint32_t frames; uint32_t interval_ms; } cam_trigger;
43			/* status: 0 ok, >0 rpicam exit code (128+sig if killed), <0 -errno in camd */
44			struct { uint64_t event_id; int32_t status; uint32_t frames; } cam_done;
45			struct { float rms; float flux; float band[PSS_NBANDS]; } mic;
46		} u;
47	};
48	
49	const char *pss_role_name(uint32_t role);
50	
51	/* Zeroes *m (no uninitialised padding on the wire), sets type and mono_ns = now. */
52	void pss_msg_init(struct pss_msg *m, uint16_t type);
53	
54	/* "$PSS_RUN_DIR/hub.sock". Returns 0 or -1 (path too long). */
55	int ipc_sock_path(char *buf, size_t n);
56	
57	/* Nonblocking listening socket at path (stale socket file removed). fd or -1, logged. */
58	int ipc_listen(const char *path);
59	/* Nonblocking connected socket. fd or -1 with errno set; not logged (callers retry). */
60	int ipc_connect(const char *path);
61	
62	/* 0 or -1 with errno. */
63	int ipc_send(int fd, struct pss_msg *m);
64	/* 1 = message, 0 = peer closed, -1 = error with errno (EAGAIN, EBADMSG size, EPROTO version). */
65	int ipc_recv(int fd, struct pss_msg *m);
66	
67	#endif
