76			pss_log("gpiod_chip_open %s: %s", chip_path, strerror(errno));
77			ret = (errno == ENOENT || errno == ENODEV) ? EXIT_DEVICE_GONE : 1;
78			goto out;
79		}
80		ls = gpiod_line_settings_new();
81		lc = gpiod_line_config_new();
82		rc = gpiod_request_config_new();
83		if (ls == NULL || lc == NULL || rc == NULL) {
84			pss_log("gpiod: out of memory");
85			goto out;
86		}
87		if (gpiod_line_settings_set_direction(ls, GPIOD_LINE_DIRECTION_INPUT) != 0 ||
88		    gpiod_line_settings_set_bias(ls, GPIOD_LINE_BIAS_PULL_UP) != 0) {
89			pss_log("gpiod line settings: %s", strerror(errno));
90			goto out;
91		}
92		if (p->poll_ms == 0 &&
93		    (gpiod_line_settings_set_edge_detection(ls, GPIOD_LINE_EDGE_BOTH) != 0 ||
94		     gpiod_line_settings_set_event_clock(ls, GPIOD_LINE_CLOCK_MONOTONIC) != 0)) {
95			pss_log("gpiod edge settings: %s", strerror(errno));
96			goto out;
97		}
98		if (gpiod_line_config_add_line_settings(lc, &p->offset, 1, ls) != 0) {
99			pss_log("gpiod_line_config_add_line_settings: %s", strerror(errno));
100			goto out;
101		}
102		gpiod_request_config_set_consumer(rc, "pird");
103		p->req = gpiod_chip_request_lines(p->chip, rc, lc);
104		if (p->req == NULL) {
105			pss_log("gpiod_chip_request_lines %s line %u: %s", chip_path, p->offset, strerror(errno));
106			goto out;
107		}
108		v = gpiod_line_request_get_value(p->req, p->offset);
109		if (v == GPIOD_LINE_VALUE_ERROR) {
110			pss_log("gpiod_line_request_get_value: %s", strerror(errno));
111			goto out;
112		}
113		*level = v == GPIOD_LINE_VALUE_ACTIVE;
114	
115		if (p->poll_ms == 0) {
116			p->evbuf = gpiod_edge_event_buffer_new(EVBUF_SIZE);
117			if (p->evbuf == NULL) {
118				pss_log("gpiod_edge_event_buffer_new: %s", strerror(errno));
119				goto out;
120			}
121			p->fd = gpiod_line_request_get_fd(p->req);
122		} else {
123			int64_t period = (int64_t)p->poll_ms * PSS_NS_PER_MS;
124	
125			p->fd = pss_timerfd(period, period);
126			if (p->fd < 0)
127				goto out;
128		}
129		ret = 0;
130	out:
131		if (rc != NULL)
132			gpiod_request_config_free(rc);
133		if (lc != NULL)
134			gpiod_line_config_free(lc);
135		if (ls != NULL)
136			gpiod_line_settings_free(ls);
137		if (ret != 0)
138			src_close(p);
139		return ret;
140	}
141	
142	static void on_edge(struct pss_client *cl, struct pir_filter *f, int rising, int64_t ts_ns, int64_t now_ns, int irq)
143	{
144		enum pir_verdict v = pir_filter_edge(f, rising, ts_ns);
145		struct pss_msg m;
146	
147		/* In IRQ mode ts is the kernel's interrupt timestamp, so now - ts is the
148		 * edge-to-userspace latency that B measures. In poll mode ts == now. */
149		if (irq)
150			pss_log("edge %s lat=%" PRId64 "us%s", rising ? "rise" : "fall", (now_ns - ts_ns) / 1000,
151				v == PIR_WARMUP ? " (warm-up, ignored)" : v == PIR_DUPLICATE ? " (duplicate, ignored)" : "");
152		else
153			pss_log("edge %s (poll)%s", rising ? "rise" : "fall",
154				v == PIR_WARMUP ? " (warm-up, ignored)" : v == PIR_DUPLICATE ? " (duplicate, ignored)" : "");
155		if (v != PIR_FORWARD)
156			return;
157		pss_msg_init(&m, PSS_MSG_PIR_EDGE);
158		m.mono_ns = ts_ns;
159		m.u.pir.rising = rising ? 1 : 0;
160		client_send(cl, &m);
161	}
162	
163	/* Returns 0, or an exit code. */
164	static int src_readable(struct pir_src *p, struct pss_client *cl, struct pir_filter *f)
165	{
166		int64_t now;
167	
168		if (p->poll_ms == 0) {
169			int n = gpiod_line_request_read_edge_events(p->req, p->evbuf, EVBUF_SIZE);
170	
171			if (n < 0) {
172				pss_log("gpiod_line_request_read_edge_events: %s", strerror(errno));
173				return errno == ENODEV ? EXIT_DEVICE_GONE : 1;
174			}
175			now = pss_mono_ns();
176			for (int i = 0; i < n; i++) {
177				struct gpiod_edge_event *ev = gpiod_edge_event_buffer_get_event(p->evbuf, (unsigned long)i);
178	
179				on_edge(cl, f, gpiod_edge_event_get_event_type(ev) == GPIOD_EDGE_EVENT_RISING_EDGE,
180					(int64_t)gpiod_edge_event_get_timestamp_ns(ev), now, 1);
181			}
182			return 0;
183		}
184	
185		if (pss_timerfd_drain(p->fd) != 0)
186			return 1;
187		enum gpiod_line_value v = gpiod_line_request_get_value(p->req, p->offset);
188		if (v == GPIOD_LINE_VALUE_ERROR) {
189			pss_log("gpiod_line_request_get_value: %s", strerror(errno));
190			return errno == ENODEV ? EXIT_DEVICE_GONE : 1;
191		}
192		now = pss_mono_ns();
193		if ((v == GPIOD_LINE_VALUE_ACTIVE) != f->level)
194			on_edge(cl, f, v == GPIOD_LINE_VALUE_ACTIVE, now, now, 0);
195		return 0;
196	}
197	
198	static void send_heartbeat(struct pss_client *cl, const struct pir_filter *f)
199	{
200		struct pss_msg m;
201	
202		pss_msg_init(&m, PSS_MSG_HEARTBEAT);
203		m.u.hb.dropped = cl->dropped;
204		m.u.hb.count = f->forwarded;
205		client_send(cl, &m);
206	}
207	
208	int main(int argc, char **argv)
209	{
210		static const struct option opts[] = {
211			{ "chip", required_argument, NULL, 'c' },
212			{ "line", required_argument, NULL, 'l' },
213			{ "poll", required_argument, NULL, 'p' },
214			{ "warmup", required_argument, NULL, 'w' },
215			{ "help", no_argument, NULL, 'h' },
216			{ NULL, 0, NULL, 0 },
217		};
218		const int sigs[] = { SIGINT, SIGTERM };
219		const char *chip_path = "/dev/gpiochip0";
220		struct pir_src src = { .fd = -1 };
221		struct pss_client cl;
222		struct pir_filter filter;
223		uint32_t line = 17, warmup_s = 60;
224		int sig_fd = -1, hb_fd = -1, level = 0, armed = 0, code = 1, opt;
225	
226		pss_log_init("pird");
227		cl.fd = -1;
228		while ((opt = getopt_long(argc, argv, "", opts, NULL)) != -1) {
229			switch (opt) {
230			case 'c': chip_path = optarg; break;
231			case 'l':
232				if (pss_parse_u32(optarg, 0, 1023, &line) != 0) { usage(); return EXIT_USAGE; }
233				break;
234			case 'p':
235				if (pss_parse_u32(optarg, 0, 10000, &src.poll_ms) != 0) { usage(); return EXIT_USAGE; }
236				break;
237			case 'w':
238				if (pss_parse_u32(optarg, 0, 600, &warmup_s) != 0) { usage(); return EXIT_USAGE; }
239				break;
240			default: usage(); return opt == 'h' ? 0 : EXIT_USAGE;
241			}
242		}
243		src.offset = line;
244	
245		sig_fd = pss_signalfd(sigs, 2);
246		if (sig_fd < 0)
247			goto out;
248		if (client_init(&cl, PSS_ROLE_PIR) != 0)
249			goto out;
250		code = src_open(&src, chip_path, &level);
251		if (code != 0)
252			goto out;
253		code = 1;
254		hb_fd = pss_timerfd(HB_PERIOD_NS, HB_PERIOD_NS);
255		if (hb_fd < 0)
256			goto out;
257		pir_filter_init(&filter, pss_mono_ns(), (int64_t)warmup_s * PSS_NS_PER_S, level);
258		pss_log("start pid=%d chip=%s line=%" PRIu32 " mode=%s level=%d; warm-up, edges ignored until T+%" PRIu32 "s",
259			(int)getpid(), chip_path, line, src.poll_ms ? "poll" : "irq", level, warmup_s);
260		if (src.poll_ms)
261			pss_log("polling every %" PRIu32 " ms", src.poll_ms);
262	
263		for (;;) {
264			struct pollfd pfd[4];
265			int64_t now = pss_mono_ns();
266			int nfds = 3, timeout;
267	
268			if (client_poll_connect(&cl, now))
269				send_heartbeat(&cl, &filter);
270			if (!armed && now >= filter.warmup_until_ns) {
271				pss_log("warm-up over, armed (line level=%d)", filter.level);
272				armed = 1;
273			}
274	
275			pfd[0] = (struct pollfd){ .fd = sig_fd, .events = POLLIN };
276			pfd[1] = (struct pollfd){ .fd = src.fd, .events = POLLIN };
277			pfd[2] = (struct pollfd){ .fd = hb_fd, .events = POLLIN };
278			if (cl.fd >= 0)
279				pfd[nfds++] = (struct pollfd){ .fd = cl.fd, .events = POLLIN };
280			timeout = cl.fd < 0 ? 250 : armed ? -1 : 1000;
281	
282			if (poll(pfd, (nfds_t)nfds, timeout) < 0) {
283				if (errno == EINTR)
284					continue;
285				pss_log("poll: %s", strerror(errno));
286				goto out;
287			}
288			if (pfd[0].revents & POLLIN) {
289				struct signalfd_siginfo si;
290	
291				if (read(sig_fd, &si, sizeof si) != (ssize_t)sizeof si)
292					pss_log("signalfd read: %s", strerror(errno));
293				else
294					pss_log("signal %u, exiting (forwarded=%" PRIu64 " dropped=%" PRIu64 ")",
295						si.ssi_signo, filter.forwarded, cl.dropped);
296				code = 0;
297				goto out;
298			}
299			if (pfd[1].revents & (POLLIN | POLLERR | POLLHUP)) {
300				int r = src_readable(&src, &cl, &filter);
301	
302				if (r != 0) {
303					code = r;
304					if (code == EXIT_DEVICE_GONE)
305						pss_log("GPIO device gone; exit 3");
306					goto out;
307				}
308			}
309			if (pfd[2].revents & POLLIN) {
310				if (pss_timerfd_drain(hb_fd) != 0)
311					goto out;
312				send_heartbeat(&cl, &filter);
313			}
314			if (nfds == 4 && pfd[3].revents) {
315				struct pss_msg m;
316				int r = ipc_recv(cl.fd, &m);
317	
318				if (r == 0)
319					client_disconnect(&cl, now, "hub closed");
320				else if (r < 0 && errno != EAGAIN)
321					client_disconnect(&cl, now, strerror(errno));
322			}
323		}
324	out:
325		client_close(&cl);
326		src_close(&src);
327		if (hb_fd >= 0)
328			close(hb_fd);
329		if (sig_fd >= 0)
330			close(sig_fd);
331		return code;
332	}
